package npm

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestConstraintAutoGenerated exercises the node-semver derived test cases.
func TestConstraintAutoGenerated(t *testing.T) {
	for _, tc := range autoGeneratedTests {
		t.Run(tc.version+"|"+tc.constraint, func(t *testing.T) {
			c, err := NewConstraints(tc.constraint)
			require.NoError(t, err)
			v, err := NewVersion(tc.version)
			require.NoError(t, err)
			assert.Equal(t, tc.want, c.Check(v), "version=%q constraint=%q", tc.version, tc.constraint)
		})
	}
}
